mapper.select:
select #{VALID_STATUS_05} as validStatus, A.TOTLE_TRADE_ID as bussId, A.PORTFOLIO_ID as portfolioId, C.FINPROD_MARKET_ID as prodId, C.FINPROD_ABBR as prodAbbr, D.SALE_DEPARTMENT as saleDepartment, A.VDATE as payintStartDate, A.MDATE as payintEndDate, A.PRIN_AMT as prinAmt, B.INTEREST as theoryCusProfit, A.INT_AMT as actCusProfit, C.CCY as ccy, D.IS_LAY as isLay, A.SETTLE_DATE as payDate, C.FINPROD_ID as finprodId from TRD_FIN_PRODUCT_DEAL_TOTAL A left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID left join FIN_PRODUCT C on A.FINPROD_ID = C.FINPROD_ID left join FIN_PRODUCT_ADD D on C.FINPROD_ID = D.FINPROD_ID where A.PS = #{PS_ZJSX}
and A.FINPROD_TYPE2 = #{FINPROD_TYPE_LCCP}
AND C.FINPROD_MARKET_ID IN
#{item}
AND A.MDATE >= STR_TO_DATE(#{payIntEndDateBegin}, '%Y-%m-%d')
AND A.MDATE <= STR_TO_DATE(#{payIntEndDateEnd}, '%Y-%m-%d')
AND A.PORTFOLIO_ID IN
#{item}
AND A.SETTLE_DATE >= STR_TO_DATE(#{payDateBegin}, '%Y-%m-%d')
AND A.SETTLE_DATE <= STR_TO_DATE(#{payDateEnd}, '%Y-%m-%d')
AND C.PROFIT_TYPE = #{PROFIT_TYPE}
AND A.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} AND (A.IS_CANCEL IS NULL OR A.IS_CANCEL = #{YES_NO_N,jdbcType=VARCHAR})
UNION ALL
select #{VALID_STATUS_06} as validStatus, A.TOTLE_TRADE_ID as bussId, A.PORTFOLIO_ID as portfolioId, C.FINPROD_MARKET_ID as prodId, C.FINPROD_ABBR as prodAbbr, D.SALE_DEPARTMENT as saleDepartment, A.VDATE as payintStartDate, A.MDATE as payintEndDate, A.PRIN_AMT as prinAmt, B.INTEREST as theoryCusProfit, A.INT_AMT as actCusProfit, C.CCY as ccy, D.IS_LAY as isLay, A.SETTLE_DATE as payDate, C.FINPROD_ID as finprodId from TRD_FIN_PRODUCT_DEAL_TOTAL A left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID left join FIN_PRODUCT C on A.FINPROD_ID = C.FINPROD_ID left join FIN_PRODUCT_ADD D on C.FINPROD_ID = D.FINPROD_ID where A.PS = #{PS_ZJSX} and A.IS_CANCEL = #{YES} and A.FINPROD_TYPE2 = #{FINPROD_TYPE_LCCP}
AND C.FINPROD_MARKET_ID IN
#{item}
AND A.MDATE >= STR_TO_DATE(#{payIntEndDateBegin}, '%Y-%m-%d')
AND A.MDATE <= STR_TO_DATE(#{payIntEndDateEnd}, '%Y-%m-%d')
AND A.PORTFOLIO_ID IN
#{item}
AND A.SETTLE_DATE >= STR_TO_DATE(#{payDateBegin}, '%Y-%m-%d')
AND A.SETTLE_DATE <= STR_TO_DATE(#{payDateEnd}, '%Y-%m-%d')
AND C.PROFIT_TYPE = #{PROFIT_TYPE}
AND A.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR}
order by validStatus, bussId, portfolioId, prodId, payintStartDate

select FIN_PRODUCT.FINPROD_ID id, concat_ws('', FINPROD_MARKET_ID, ':', FINPROD_ABBR) text
from FIN_PRODUCT, FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY,TRD_FIN_PRODUCT_DEAL_TOTAL
where FIN_PRODUCT.FINPROD_ID =TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID
and FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeProd}
and FIN_PRODUCT.P_FINPROD_ID IS NULL
and FIN_PRODUCT.PROFIT_TYPE = '02'

	and FIN_PRODUCT_ADD.ISSUE_STATUS = #{issueStatus}


and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID

	and (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',#{search},'%')
	or FIN_PRODUCT.FINPROD_ABBR like concat('%',#{search},'%'))



		and FIN_PRODUCT.FINPROD_ID = #{initValue}



			and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
